/**
 * One of the five Core Web Vitals metric names emitted by web-vitals.
 */
export type CwvMetricName = (typeof CwvMetricName)[keyof typeof CwvMetricName];

export const CwvMetricName = {
  LCP: "LCP",
  INP: "INP",
  CLS: "CLS",
  FCP: "FCP",
  TTFB: "TTFB",
} as const;

/**
 * web-vitals' three-bucket rating for a metric value.
 */
export type CwvRating = (typeof CwvRating)[keyof typeof CwvRating];

export const CwvRating = {
  good: "good",
  "needs-improvement": "needs-improvement",
  poor: "poor",
} as const;

export interface CwvSampleInput {
  /**
   * The visitor's pathname at sample time (no host, no query).
   * @minLength 1
   * @maxLength 256
   */
  route: string;
  metric: CwvMetricName;
  /**
   * Metric value (milliseconds for time-based metrics, unitless for CLS).
   * @minimum 0
   */
  value: number;
  rating: CwvRating;
  /** @nullable */
  navigationType?: string | null;
  /** @nullable */
  metricId?: string | null;
}

export interface SiteHealthCwvRow {
  route: string;
  metric: CwvMetricName;
  sampleCount: number;
  p50: number;
  p75: number;
  p90: number;
}

export interface SiteHealthAltCoverage {
  totalImageMedia: number;
  /** Rows whose alt text matches the deterministic "Image: …" placeholder pattern. */
  placeholderCount: number;
  reviewedCount: number;
  /** reviewedCount / totalImageMedia. 0 when total is 0. */
  coverageRatio: number;
}

export interface SiteHealthRedirectRow {
  id: string;
  sourcePath: string;
  targetPath: string;
  statusCode: number;
  active: boolean;
  hitCount: number;
  /** @nullable */
  lastHitAt?: string | null;
}

export interface SiteHealthRedirects {
  totalActive: number;
  /** Sum of `hit_count` across all active redirects. */
  totalHits: number;
  /** Up to 10 most-hit active redirects. */
  top: SiteHealthRedirectRow[];
  /** Redirects whose target is itself the source of another redirect (one-hop chain detection). */
  chains: SiteHealthRedirectRow[];
}

export interface SiteHealthAiPromptCacheDay {
  /** ISO calendar day, e.g. `2026-05-03`. */
  utcDay: string;
  model: string;
  requestCount: number;
  /** Requests in the day where `cache_read_input_tokens > 0`. */
  warmRequestCount: number;
  inputTokens: number;
  outputTokens: number;
  cacheCreationInputTokens: number;
  cacheReadInputTokens: number;
  /** Fraction of input-equivalent tokens served from cache (0–1). */
  hitRate: number;
  /** Fraction of requests in the day that had any cache read (0–1). */
  requestHitRate: number;
  /** Estimated USD cost if caching were disabled (input + cache_creation + cache_read all billed at the standard input rate, plus output). */
  estimatedFullCostUsd: number;
  /** Estimated USD cost actually billed (cache_creation at 1.25x, cache_read at 0.1x, input + output at 1.0x). */
  estimatedActualCostUsd: number;
  /** estimatedFullCostUsd − estimatedActualCostUsd. Negative on cold-cache days where the surcharge dominates. */
  estimatedSavingsUsd: number;
}

export type SiteHealthAiPromptCacheAlertSeverity =
  (typeof SiteHealthAiPromptCacheAlertSeverity)[keyof typeof SiteHealthAiPromptCacheAlertSeverity];

export const SiteHealthAiPromptCacheAlertSeverity = {
  ok: "ok",
  page: "page",
  "insufficient-data": "insufficient-data",
} as const;

export interface SiteHealthAiPromptCacheAlert {
  severity: SiteHealthAiPromptCacheAlertSeverity;
  message?: string | null;
}

export type SiteHealthAiPromptCacheThresholds = {
  hitRate: number;
  minRequests: number;
};

export interface SiteHealthAiPromptCache {
  daily: SiteHealthAiPromptCacheDay[];
  /** Most recent fully-elapsed UTC day with rollup data, or null if none. */
  latestComplete: string | null;
  /** Per-token hit rate aggregated across all models on `latestComplete`. */
  latestHitRate: number;
  latestRequestCount: number;
  /** Sum of `estimatedSavingsUsd` over all `daily` rows in the window. */
  estimatedSavingsUsd: number;
  alert: SiteHealthAiPromptCacheAlert;
  thresholds: SiteHealthAiPromptCacheThresholds;
}

export interface SiteHealthAiChatDay {
  day: string;
  inputTokens: number;
  outputTokens: number;
  callCount: number;
}

export type SiteHealthAiChatToday = {
  inputTokens: number;
  outputTokens: number;
  callCount: number;
};

/**
 * Daily-rollup token spend for `/ai/chat`, plus the active per-session and global caps. Only the global scope is surfaced on the dashboard; the per-session and per-IP scopes drive enforcement only.
 */
export interface SiteHealthAiChat {
  dailyCapPerSession: number;
  dailyCapGlobal: number;
  today: SiteHealthAiChatToday;
  days: SiteHealthAiChatDay[];
}

export interface SiteHealthSnapshot {
  generatedAt: string;
  windowDays: number;
  cwv: SiteHealthCwvRow[];
  altText: SiteHealthAltCoverage;
  redirects: SiteHealthRedirects;
  aiPromptCache: SiteHealthAiPromptCache;
  aiChat: SiteHealthAiChat;
}

